import os

# First, let's check what files are in the current directory to find the database
print("Current directory:", os.getcwd())
print("\nFiles in current directory:")
for file in os.listdir('.'):
    print(f"- {file}")

# Let's also check for any .db or .sqlite files
print("\nLooking for database files:")
for file in os.listdir('.'):
    if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
        print(f"Found: {file}")
        db_path = file
        break
else:
    print("No database files found. Let's check one level up:")
    parent_dir = os.path.dirname(os.getcwd())
    for file in os.listdir(parent_dir):
        if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
            print(f"Found: {file} in parent directory")
            db_path = os.path.join(parent_dir, file)
            break
    else:
        print("No database files found. Please specify the correct path.")
        db_path = None

if db_path:
    print(f"\nUsing database path: {db_path}")
    print(f"File exists: {os.path.exists(db_path)}")
    if os.path.exists(db_path):
        print(f"File size: {os.path.getsize(db_path)} bytes")
